<template>
  <main class="attendance-page">
    <header class="attendance-heading"><div><h1>考勤核查</h1><p>排班与闸机、手机记录交叉核对</p></div><div class="heading-tools"><el-select v-model="historyId" :disabled="busy" placeholder="历史导入" aria-label="选择历史导入" @change="loadReport"><el-option v-for="r in history" :key="r.id" :value="String(r.id)" :label="`${r.title} · ${r.created_at?.slice(0,10)}`" /></el-select></div></header>

    <section class="attendance-sources" aria-label="导入文件">
      <div v-for="kind in ['schedule','attendance']" :key="kind" class="source-item">
        <span class="source-icon"><el-icon><Document /></el-icon></span><div class="source-copy"><b>{{ kind==='schedule'?'排班表':'考勤表' }}</b><span :title="sourceName(kind)">{{ sourceName(kind) || '请选择 .xlsx 文件（最大10MB）' }}</span></div>
        <span v-if="files[kind]" class="source-state">待校验</span><span v-else-if="analysis" class="source-state imported"><el-icon><CircleCheckFilled /></el-icon>已导入</span>
        <label class="file-select">{{ sourceName(kind)?'更换文件':'选择文件' }}<input :aria-label="kind==='schedule'?'上传排班表':'上传考勤表'" type="file" accept=".xlsx" :disabled="busy" @change="chooseFile($event,kind)" /></label>
        <button v-if="report && !files[kind]" class="text-button" :disabled="busy" @click="downloadSource(kind)">下载</button>
      </div>
      <div class="source-actions"><label class="period-select"><span>排班月份</span><input v-model="period" type="month" aria-label="排班月份" :disabled="busy || Boolean(report)&&!files.schedule&&!files.attendance" /></label><button class="primary" :disabled="busy || !canAnalyze" @click="analyze">{{ busy?'正在校验…':analysis?'重新分析':'校验并分析' }}</button></div>
    </section>

    <section v-if="validationErrors.length" class="validation-panel errors" role="alert"><b>{{ errorMessage }}</b><ul><li v-for="(issue,i) in validationErrors" :key="i">{{ issueText(issue) }}</li></ul><p>本次文件未保存，请修正后重新选择。</p></section>
    <section v-if="analysis?.warnings.length" class="validation-panel warnings"><details :open="!report"><summary><el-icon><WarningFilled /></el-icon>{{ analysis.warnings.length }} 项导入提醒 · 考勤截至 {{ analysis.coverage.to }}</summary><ul><li v-for="(issue,i) in analysis.warnings" :key="i">{{ issueText(issue) }}</li></ul></details></section>
    <p v-if="feedback" class="page-feedback" role="status">{{ feedback }}</p>

    <div v-if="analysis" class="attendance-workspace">
      <section class="attendance-list">
        <nav class="result-tabs" aria-label="核查类型"><button v-for="t in resultTabs" :key="t.key" :class="{active:resultTab===t.key}" @click="resultTab=t.key;page=1">{{ t.label }} <span>{{ t.count }}</span></button></nav>
        <div class="attendance-filters"><el-select v-model="shiftFilter" placeholder="全部班次" aria-label="班次筛选" @change="page=1"><el-option label="全部班次" value=""/><el-option v-for="s in shiftOptions" :key="s" :label="s" :value="s"/></el-select><el-input v-model="keyword" placeholder="请输入姓名或工号" aria-label="搜索姓名或工号" clearable @input="page=1"><template #prefix><el-icon><Search /></el-icon></template></el-input><el-select v-model="minAdvance" aria-label="提前时长筛选" @change="page=1"><el-option label="全部提前时长" :value="0"/><el-option label="提前至少5分钟" :value="300"/><el-option label="提前至少10分钟" :value="600"/><el-option label="提前至少30分钟" :value="1800"/></el-select><button :disabled="!filtered.length" @click="exportCsv"><el-icon><Upload /></el-icon>导出清单</button></div>
        <div class="observation-tools"><span>{{ analysis.summary.matchedPeople }} / {{ analysis.summary.people }} 人工号匹配 · {{ analysis.summary.eventCount }} 条有效记录</span><label>下班后观察 <select v-model.number="hours" aria-label="下班后观察时段" :disabled="busy"><option :value="0.5">30分钟</option><option :value="1">1小时</option><option :value="2">2小时</option><option :value="4">4小时</option></select></label><small v-if="hours!==analysis.options.observationHours">点击“重新分析”应用</small></div>
        <div class="result-table-scroll"><table class="result-table"><thead><tr><th>人员</th><th>排班日期 / 班次</th><th>闸机出门</th><th>提前时长</th><th>核查类型</th><th>操作</th></tr></thead><tbody><tr v-for="r in paged" :key="r.key" :class="{selected:selectedKey===r.key}" @click="selectRow(r)"><td><b>{{r.name}}</b><small>{{r.id}}</small></td><td>{{r.date.slice(5)}}<small>{{r.shift}}</small></td><td>{{shortTime(r.earlyExit || r.afterExit || r.lateExit)}}</td><td :class="{advance:r.advanceSeconds>0}">{{duration(r.advanceSeconds)}}</td><td><span class="status-badge" :class="r.status">{{statuses[r.status]}}</span><small v-if="!r.complete && r.status!=='partial'">观察时段未覆盖</small></td><td><button class="text-button" @click.stop="selectRow(r)">查看</button></td></tr></tbody></table></div>
        <p v-if="!filtered.length" class="empty-result">当前筛选条件下没有记录。</p>
        <div class="list-footer"><p><el-icon><InfoFilled /></el-icon>缺少出门记录不能确定离场时间；GPS 记录不能确认手机操作者。</p><el-pagination v-if="filtered.length>20" v-model:current-page="page" :page-size="20" :total="filtered.length" layout="prev,pager,next" size="small"/></div>
      </section>

      <aside ref="detailPanel" class="attendance-detail" aria-label="记录详情">
        <template v-if="selected"><header><h2>记录详情</h2><button class="text-button mobile-detail-back" @click="selectedKey=''">收起</button></header><div class="person-title"><b>{{selected.name}}</b><span>工号 {{selected.id}}</span></div><p>{{selected.date}} · {{selected.shift}}</p>
          <p v-if="selectedOutsideFilter" class="detail-caution">此记录不在当前筛选结果中；当前备注尚未保存。</p>
          <div class="detail-result" :class="selected.status"><span>{{statuses[selected.status]}}</span><strong v-if="selected.advanceSeconds!==null">{{duration(selected.advanceSeconds)}}</strong></div>
          <h3>考勤记录时间线</h3><ol class="evidence-timeline"><li v-for="(event,i) in selected.timeline" :key="i" :class="event.type"><time>{{event.time.slice(5)}}</time><el-icon><component :is="eventIcon(event.type)"/></el-icon><div><b>{{eventLabel(event.type)}}</b><small v-if="event.device">{{event.device}}<template v-if="event.direction"> · {{event.direction}}</template></small><small v-if="event.gate">{{event.gate}}</small><small v-if="event.sourceRow">考勤表第 {{event.sourceRows.join('、')}} 行</small></div></li></ol>
          <div class="detail-context"><p>下班前返回：{{selected.returnedAt || '未查到'}}</p><p>下班后观察截止：{{selected.observationEnd}}</p><p v-if="selected.lateExit">延长复查发现出门：{{selected.lateExit}}</p><p v-if="!selected.complete" class="coverage-warning">观察时段未完整覆盖，不能据此判定缺出门。</p><p v-if="selected.status==='missing_exit' && !selected.extendedComplete">更晚时段的数据也未覆盖，缺出门线索尚需补充记录。</p></div>
          <p class="detail-caution"><el-icon><WarningFilled /></el-icon>{{selected.earlyCount?'存在下班前出门记录；手机操作者需另行核查。':'缺少出门记录仅为线索，需结合人工通道监控核查。'}}</p>
          <label class="review-note">核查备注<el-input v-model="noteDraft" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="记录监控核对、外出审批等情况" :disabled="!report || busy"/></label><button :disabled="!report || busy || noteDraft===(notes[selected.key]?.note||'')" @click="saveNote">保存备注</button><small v-if="!report" class="unsaved-note">确认导入后可保存核查备注。</small>
        </template><p v-else class="empty-detail">选择一条记录查看时间线。</p>
      </aside>
    </div>
    <section v-else-if="!busy" class="attendance-empty"><el-icon><DocumentChecked /></el-icon><h2>导入排班表和考勤表开始核查</h2><p>按工号和实际班次匹配，识别提前出门、出门后返回及缺出门线索。</p><p>夜班“24:00—8:00”按排班日期当天 00:00—08:00 计算。</p></section>

    <el-dialog v-model="confirmImport" title="请核对导入提醒" width="min(640px, calc(100vw - 28px))" :close-on-click-modal="false"><p>文件格式和关键字段已通过校验，以下问题会影响结果范围。确认后保存本次导入，原始文件和结果可由系统管理员管理。</p><ul class="import-warning-list"><li v-for="(issue,i) in analysis?.warnings||[]" :key="i">{{issueText(issue)}}</li></ul><template #footer><el-button @click="confirmImport=false" :disabled="busy">返回查看</el-button><el-button type="primary" :loading="busy" @click="persistImport">确认并保存导入</el-button></template></el-dialog>
  </main>
</template>

<script setup>
import {computed,nextTick,onMounted,ref,watch} from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import {Document,DocumentChecked,CircleCheckFilled,WarningFilled,Search,Upload,InfoFilled,Clock,Switch,Location} from '@element-plus/icons-vue'
import {office,downloadAttendanceSource,saveBlob} from '../api/attendance'
import {attendanceStatuses as statuses,duration,shortTime,attendanceCsv} from '../utils/attendance-display.mjs'

const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10)
const period=ref(today.slice(0,7)),hours=ref(2),files=ref({schedule:null,attendance:null}),analysis=ref(null),report=ref(null),notes=ref({}),history=ref([]),historyId=ref(''),busy=ref(false),feedback=ref(''),validationErrors=ref([]),errorMessage=ref(''),confirmImport=ref(false)
const resultTab=ref('signals'),keyword=ref(''),shiftFilter=ref(''),minAdvance=ref(0),page=ref(1),selectedKey=ref(''),noteDraft=ref('')
const sourceName=kind=>files.value[kind]?.name || analysis.value?.sources?.[kind]?.name || ''
const issueText=issue=>[issue.source,issue.row?`第${issue.row}行`:'',issue.column?`第${issue.column}列`:'',issue.message].filter(Boolean).join(' · ')
const canAnalyze=computed(()=>Boolean(files.value.schedule&&files.value.attendance) || Boolean(report.value&&!files.value.schedule&&!files.value.attendance))
const rows=computed(()=>analysis.value?.results||[])
const signals=r=>['early','missing_exit','returned','late_exit','missing_no_gps'].includes(r.status)
const resultTabs=computed(()=>[{key:'signals',label:'全部线索',count:rows.value.filter(signals).length},{key:'early',label:'提前出门',count:rows.value.filter(r=>r.status==='early').length},{key:'missing_exit',label:'缺出门记录',count:rows.value.filter(r=>r.status==='missing_exit').length},{key:'all',label:'全部排班',count:rows.value.length}])
const shiftOptions=computed(()=>[...new Set(rows.value.map(r=>r.shift))].sort())
const filtered=computed(()=>rows.value.filter(r=>(resultTab.value==='all'||resultTab.value==='signals'&&signals(r)||r.status===resultTab.value)&&(!shiftFilter.value||r.shift===shiftFilter.value)&&(!keyword.value||`${r.name} ${r.id}`.toLowerCase().includes(keyword.value.trim().toLowerCase()))&&(!minAdvance.value||r.advanceSeconds>=minAdvance.value)))
const paged=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20))
const selected=computed(()=>rows.value.find(r=>r.key===selectedKey.value))
const detailPanel=ref(null)
const selectedOutsideFilter=computed(()=>selected.value&&!filtered.value.some(r=>r.key===selectedKey.value))
watch(selectedKey,()=>{noteDraft.value=notes.value[selectedKey.value]?.note||''})
watch(filtered,value=>{if(!value.some(r=>r.key===selectedKey.value)&&noteDraft.value===(notes.value[selectedKey.value]?.note||''))selectedKey.value=value[0]?.key||''},{flush:'post'})
async function selectRow(row){
  if(busy.value)return
  if(row.key!==selectedKey.value&&noteDraft.value!==(notes.value[selectedKey.value]?.note||'')){try{await ElMessageBox.confirm('当前备注尚未保存，切换后将放弃修改。','切换记录',{confirmButtonText:'切换',cancelButtonText:'取消'})}catch{return}}
  selectedKey.value=row.key
  if(window.innerWidth<=950){await nextTick();detailPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
}
const eventLabel=type=>({in:'闸机进门',out:'闸机出门',gps:'手机 GPS',start:'应上班',end:'应下班'}[type])
const eventIcon=type=>({in:Switch,out:Switch,gps:Location,start:Clock,end:Clock}[type])
function chooseFile(event,kind){
  const file=event.target.files?.[0];if(!file)return
  if(!/\.xlsx$/i.test(file.name)||file.size>10*1024*1024||file.size===0){ElMessage.error('请选择有效的 .xlsx 文件，大小不能超过10MB');event.target.value='';return}
  files.value={...files.value,[kind]:file};validationErrors.value=[];feedback.value=analysis.value?'新文件待校验；下方仍为上一次分析结果，点击“重新分析”后更新。':'文件待校验，请同时选择排班表和考勤表。'
  if(kind==='schedule') { const m=file.name.match(/(20\d{2})年\s*(\d{1,2})月/); if(m&&+m[2]>=1&&+m[2]<=12)period.value=`${m[1]}-${m[2].padStart(2,'0')}` }
  event.target.value=''
}
function importForm(){const data=new FormData();data.append('schedule',files.value.schedule);data.append('attendance',files.value.attendance);data.append('month',period.value);data.append('observationHours',hours.value);return data}
function showImportError(error){errorMessage.value=error.response?.data?.msg||'文件校验失败，请检查文件和网络';validationErrors.value=error.response?.data?.details?.length?error.response.data.details:[{message:errorMessage.value}];feedback.value=''}
async function analyze(){
  busy.value=true;validationErrors.value=[];feedback.value=''
  try{
    if(report.value&&!files.value.schedule&&!files.value.attendance){const r=await office.post(`/attendance/reports/${report.value.id}/reanalyze`,{observationHours:hours.value,revision:report.value.revision});applyReport(r.data);feedback.value='已按新的观察时段重新分析。';return}
    const result=await office.post('/attendance/preview',importForm(),{validationRequest:true});analysis.value=result.data;report.value=null;notes.value={};selectedKey.value=analysis.value.results.find(signals)?.key||analysis.value.results[0]?.key||'';page.value=1;resultTab.value='signals';
    if(analysis.value.warnings.length)confirmImport.value=true
    else {busy.value=false;await persistImport()}
  }catch(error){showImportError(error)}finally{busy.value=false}
}
async function persistImport(){
  busy.value=true
  try{const data=importForm();data.append('acknowledgeWarnings','true');const result=await office.post('/attendance/reports',data,{validationRequest:true});applyReport(result.data);files.value={schedule:null,attendance:null};confirmImport.value=false;feedback.value='导入已保存，可查看记录、保存备注和导出清单。';await loadHistory()}
  catch(error){showImportError(error)}finally{busy.value=false}
}
function applyReport(data){report.value=data;analysis.value=data.analysis;notes.value=data.notes||{};historyId.value=String(data.id);period.value=data.analysis.month;hours.value=data.analysis.options.observationHours;const key=selectedKey.value;selectedKey.value='';selectedKey.value=data.analysis.results.some(r=>r.key===key)?key:data.analysis.results.find(signals)?.key||data.analysis.results[0]?.key||'';noteDraft.value=notes.value[selectedKey.value]?.note||'';page.value=1}
async function loadHistory(){const r=await office.get('/attendance/reports');history.value=r.data}
async function loadReport(id){
  if(files.value.schedule||files.value.attendance||noteDraft.value!==(notes.value[selectedKey.value]?.note||'')){try{await ElMessageBox.confirm('切换后将放弃未保存的文件选择或备注。','切换导入',{confirmButtonText:'切换',cancelButtonText:'取消'})}catch{historyId.value=report.value?String(report.value.id):'';return}}
  busy.value=true;try{const r=await office.get(`/attendance/reports/${id}`);applyReport(r.data);files.value={schedule:null,attendance:null};validationErrors.value=[];feedback.value=''}finally{busy.value=false}
}
async function saveNote(){const key=selected.value.key;busy.value=true;try{const r=await office.patch(`/attendance/reports/${report.value.id}/notes`,{entryKey:key,note:noteDraft.value,revision:report.value.revision});notes.value={...notes.value,[key]:{note:r.data.note}};report.value.revision=r.data.revision;if(selectedKey.value===key)noteDraft.value=r.data.note;ElMessage.success('核查备注已保存')}finally{busy.value=false}}
function exportCsv(){saveBlob(new Blob([attendanceCsv(filtered.value,notes.value)],{type:'text/csv;charset=utf-8'}),`原粮考勤核查_${analysis.value.month}.csv`)}
async function downloadSource(kind){await downloadAttendanceSource(report.value.id,kind,sourceName(kind))}
onMounted(async()=>{try{await loadHistory();if(history.value.length)await loadReport(String(history.value[0].id))}catch{feedback.value='历史记录加载失败，请刷新后重试。'}})
</script>

<style scoped>
